        /// <para>The application can hang any data it wants here, but the following properties are understood by SDL:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Props.AudiostreamAutoCleanupBoolean">AudiostreamAutoCleanupBoolean</see>: if true (the default), the stream be automatically cleaned up when the audio subsystem quits. If set to false, the streams will persist beyond that. This property is ignored for streams created through <c>SDL_OpenAudioDeviceStream</c>, and will always be cleaned up. Streams that are not cleaned up will still be unbound from devices when the audio subsystem quits. This property was added in SDL 3.4.0.</description></item>
        /// </list>
        /// </remarks>
        /// <param name="stream">the <see cref="CSDL.Audio.AudioStream">AudioStream</see> to query.</param>
        /// <returns>
        /// <para>(<see cref="CSDL.PropertiesID">PropertiesID</see>) Returns a valid property ID on success or 0 on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_GetAudioStreamProperties">SDL_GetAudioStreamProperties</seealso></SDLWiki>
        public static extern void GetAudioStreamProperties();

        /// <summary>
        /// <para>Get the number of bytes currently queued.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is the number of bytes put into a stream as input, not the number that can be retrieved as output. Because of several details, it's not possible to calculate one number directly from the other. If you need to know how much usable data can be retrieved right now, you should use <see cref="CSDL.Audio.AudioStream.Available">Available</see> and not this function.</para>
        /// <para>Note that audio streams can change their input format at any time, even if there is still data queued in a different format, so the returned byte count will not necessarily match the number of _sample frames_ available. Users of this API should be aware of format changes they make when feeding a stream and plan accordingly.</para>
        /// <para>Queued data is not converted until it is consumed by <see cref="CSDL.Audio.AudioStream.GetData">GetData</see>, so this value should be representative of the exact data that was put into the stream.</para>
        /// <para>If the stream has so much data that it would overflow an int, the return value is clamped to a maximum value, but no queued data is lost; if there are gigabytes of data queued, the app might need to read some of it with <see cref="CSDL.Audio.AudioStream.GetData">GetData</see> before this function's return value is no longer clamped.</para>
        /// </remarks>
        /// <param name="stream">the audio stream to query.</param>
        /// <returns>
        /// <para>(int) Returns the number of bytes queued or -1 on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_GetAudioStreamQueued">SDL_GetAudioStreamQueued</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.PutData">PutData</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.Clear">Clear</see></seealso>
        public static extern void GetAudioStreamQueued();

        /// <summary>
        /// <para>Get the name of the current audio driver.</para>
        /// </summary>
        /// <remarks>
        /// <para>The names of drivers are all simple, low-ASCII identifiers, like "alsa", "coreaudio" or "wasapi". These never have Unicode characters, and are not meant to be proper names.</para>
        /// </remarks>
        /// <returns>
        /// <para>(const char *) Returns the name of the current audio driver or NULL if no driver has been initialized.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
