        public static extern void GetCurrentAudioDriver();

        /// <summary>
        /// <para>Use this function to get the number of built-in audio drivers.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function returns a hardcoded number. This never returns a negative value; if there are no drivers compiled into this build of SDL, this function returns zero. The presence of a driver in this list does not mean it will function, it just means SDL is capable of interacting with that interface. For example, a build of SDL might have esound support, but if there's no esound server available, SDL's esound driver would fail if used.</para>
        /// <para>By default, SDL tries all drivers, in its preferred order, until one is found to be usable.</para>
        /// </remarks>
        /// <returns>
        /// <para>(int) Returns the number of built-in audio drivers.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_GetNumAudioDrivers">SDL_GetNumAudioDrivers</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.Drivers.GetAudioDriver">GetAudioDriver</see></seealso>
        public static extern void GetNumAudioDrivers();

