        public static extern void IsAudioDevicePlayback();

        /// <summary>
        /// <para>Loads a WAV from a file path.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is a convenience function that is effectively the same as:</para>
        /// <code language="c">
        /// SDL_LoadWAV_IO(SDL_IOFromFile(path, "rb"), true, spec, audio_buf, audio_len);
        /// </code>
        /// </remarks>
        /// <param name="path">the file path of the WAV file to open.</param>
        /// <param name="spec">a pointer to an <see cref="CSDL.Audio.AudioSpec">AudioSpec</see> that will be set to the WAVE data's format details on successful return.</param>
        /// <param name="audio_buf">a pointer filled with the audio data, allocated by the function.</param>
        /// <param name="audio_len">a pointer filled with the length of the audio data buffer in bytes.</param>
        /// <returns>
        /// <para>(bool) Returns true on success. <c>audio_buf</c> will be filled with a pointer to an allocated buffer containing the audio data, and <c>audio_len</c> is filled with the length of that audio buffer in bytes.</para>
        /// <para>This function returns false if the .WAV file cannot be opened, uses an unknown data format, or is corrupt; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// <para>When the application is done with the data returned in <c>audio_buf</c>, it should call <see cref="CSDL.Memory.Free">Free</see> to dispose of it.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_LoadWAV">SDL_LoadWAV</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Memory.Free">Free</see></seealso>
        /// <seealso><c>SDL_LoadWAV_IO</c></seealso>
        public static extern void LoadWAV();

        /// <summary>
        /// <para>Load the audio data of a WAVE file into memory.</para>
        /// </summary>
        /// <remarks>
        /// <para>Loading a WAVE file requires <c>src</c>, <c>spec</c>, <c>audio_buf</c> and <c>audio_len</c> to be valid pointers. The entire data portion of the file is then loaded into memory and decoded if necessary.</para>
        /// <para>Supported formats are RIFF WAVE files with the formats PCM (8, 16, 24, and 32 bits), IEEE Float (32 bits), Microsoft ADPCM and IMA ADPCM (4 bits), and A-law and mu-law (8 bits). Other formats are currently unsupported and cause an error.</para>
        /// <para>If this function succeeds, the return value is zero and the pointer to the audio data allocated by the function is written to <c>audio_buf</c> and its length in bytes to <c>audio_len</c>. The <see cref="CSDL.Audio.AudioSpec">AudioSpec</see> members <c>freq</c>, <c>channels</c>, and <c>format</c> are set to the values of the audio data in the buffer.</para>
        /// <para>It's necessary to use <see cref="CSDL.Memory.Free">Free</see> to free the audio data returned in <c>audio_buf</c> when it is no longer used.</para>
        /// <para>Because of the underspecification of the .WAV format, there are many problematic files in the wild that cause issues with strict decoders. To provide compatibility with these files, this decoder is lenient in regards to the truncation of the file, the fact chunk, and the size of the RIFF chunk. The hints <see cref="CSDL.Hints.WaveRiffChunkSize">WaveRiffChunkSize</see>, <see cref="CSDL.Hints.WaveTruncation">WaveTruncation</see>, and <see cref="CSDL.Hints.WaveFactChunk">WaveFactChunk</see> can be used to tune the behavior of the loading process.</para>
        /// <para>Any file that is invalid (due to truncation, corruption, or wrong values in the headers), too big, or unsupported causes an error. Additionally, any critical I/O error from the data source will terminate the loading process with an error. The function returns NULL on error and in all cases (with the exception of <c>src</c> being NULL), an appropriate error message will be set.</para>
        /// <para>It is required that the data source supports seeking.</para>
        /// <para>Example:</para>
        /// <code language="c">
        /// SDL_LoadWAV_IO(SDL_IOFromFile("sample.wav", "rb"), true, &amp;spec, &amp;buf, &amp;len);
        /// </code>
        /// <para>Note that the <c>SDL_LoadWAV</c> function does this same thing for you, but in a less messy way:</para>
        /// <code language="c">
        /// SDL_LoadWAV("sample.wav", &amp;spec, &amp;buf, &amp;len);
        /// </code>
        /// </remarks>
        /// <param name="src">the data source for the WAVE data.</param>
        /// <param name="closeio">if true, calls <see cref="CSDL.File.IOStream.DisposeResource">DisposeResource</see> on <c>src</c> before returning, even in the case of an error.</param>
        /// <param name="spec">a pointer to an <see cref="CSDL.Audio.AudioSpec">AudioSpec</see> that will be set to the WAVE data's format details on successful return.</param>
        /// <param name="audio_buf">a pointer filled with the audio data, allocated by the function.</param>
        /// <param name="audio_len">a pointer filled with the length of the audio data buffer in bytes.</param>
        /// <returns>
        /// <para>(bool) Returns true on success. <c>audio_buf</c> will be filled with a pointer to an allocated buffer containing the audio data, and <c>audio_len</c> is filled with the length of that audio buffer in bytes.</para>
        /// <para>This function returns false if the .WAV file cannot be opened, uses an unknown data format, or is corrupt; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// <para>When the application is done with the data returned in <c>audio_buf</c>, it should call <see cref="CSDL.Memory.Free">Free</see> to dispose of it.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_LoadWAV_IO">SDL_LoadWAV_IO</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Memory.Free">Free</see></seealso>
        /// <seealso><c>SDL_LoadWAV</c></seealso>
        public static extern void LoadWAV_IO();

        /// <summary>
        /// <para>Lock an audio stream for serialized access.</para>
        /// </summary>
        /// <remarks>
        /// <para>Each <see cref="CSDL.Audio.AudioStream">AudioStream</see> has an internal mutex it uses to protect its data structures from threading conflicts. This function allows an app to lock that mutex, which could be useful if registering callbacks on this stream.</para>
        /// <para>One does not need to lock a stream to use in it most cases, as the stream manages this lock internally. However, this lock is held during callbacks, which may run from arbitrary threads at any time, so if an app needs to protect shared data during those callbacks, locking the stream guarantees that the callback is not running while the lock is held.</para>
        /// <para>As this is just a wrapper over <see cref="CSDL.Threads.Mutex.Lock">Lock</see> for an internal lock; it has all the same attributes (recursive locks are allowed, etc).</para>
        /// </remarks>
        /// <param name="stream">the audio stream to lock.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_LockAudioStream">SDL_LockAudioStream</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.Unlock">Unlock</see></seealso>
        public static extern void LockAudioStream();

        /// <summary>
        /// <para>Mix audio data in a specified format.</para>
        /// </summary>
        /// <remarks>
        /// <para>This takes an audio buffer <c>src</c> of <c>len</c> bytes of <c>format</c> data and mixes it into <c>dst</c>, performing addition, volume adjustment, and overflow clipping. The buffer pointed to by <c>dst</c> must also be <c>len</c> bytes of <c>format</c> data.</para>
        /// <para>This is provided for convenience -- you can mix your own audio data.</para>
        /// <para>Do not use this function for mixing together more than two streams of sample data. The output from repeated application of this function may be distorted by clipping, because there is no accumulator with greater range than the input (not to mention this being an inefficient way of doing it).</para>
        /// <para>It is a common misconception that this function is required to write audio data to an output stream in an audio callback. While you can do that, <see cref="MixAudio"/> is really only needed when you're mixing a single audio stream with a volume adjustment.</para>
        /// </remarks>
        /// <param name="dst">the destination for the mixed audio.</param>
        /// <param name="src">the source audio buffer to be mixed.</param>
        /// <param name="format">the <see cref="CSDL.Audio.AudioFormat">AudioFormat</see> structure representing the desired audio format.</param>
        /// <param name="len">the length of the audio buffer in bytes.</param>
        /// <param name="volume">ranges from 0.0 - 1.0, and should be set to 1.0 for full audio volume.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_MixAudio">SDL_MixAudio</seealso></SDLWiki>
        public static extern void MixAudio();

        /// <summary>
        /// <para>Open a specific audio device.</para>
        /// </summary>
        /// <remarks>
        /// <para>You can open both playback and recording devices through this function. Playback devices will take data from bound audio streams, mix it, and send it to the hardware. Recording devices will feed any bound audio streams with a copy of any incoming data.</para>
        /// <para>An opened audio device starts out with no audio streams bound. To start audio playing, bind a stream and supply audio data to it. Unlike SDL2, there is no audio callback; you only bind audio streams and make sure they have data flowing into them (however, you can simulate SDL2's semantics fairly closely by using <c>SDL_OpenAudioDeviceStream</c> instead of this function).</para>
        /// <para>If you don't care about opening a specific device, pass a <c>devid</c> of either <see cref="CSDL.Audio.Macros.AudioDeviceDefaultPlayback">AudioDeviceDefaultPlayback</see> or <see cref="CSDL.Audio.Macros.AudioDeviceDefaultRecording">AudioDeviceDefaultRecording</see>. In this case, SDL will try to pick the most reasonable default, and may also switch between physical devices seamlessly later, if the most reasonable default changes during the lifetime of this opened device (user changed the default in the OS's system preferences, the default got unplugged so the system jumped to a new default, the user plugged in headphones on a mobile device, etc). Unless you have a good reason to choose a specific device, this is probably what you want.</para>
        /// <para>You may request a specific format for the audio device, but there is no promise the device will honor that request for several reasons. As such, it's only meant to be a hint as to what data your app will provide. Audio streams will accept data in whatever format you specify and manage conversion for you as appropriate. <see cref="CSDL.Audio.PlaybackDevice.ResolveDefaultSpec">ResolveDefaultSpec</see> can tell you the preferred format for the device before opening and the actual format the device is using after opening.</para>
        /// <para>It's legal to open the same device ID more than once; each successful open will generate a new logical <see cref="CSDL.Audio.AudioDeviceID">AudioDeviceID</see> that is managed separately from others on the same physical device. This allows libraries to open a device separately from the main app and bind its own streams without conflicting.</para>
        /// <para>It is also legal to open a device ID returned by a previous call to this function; doing so just creates another logical device on the same physical device. This may be useful for making logical groupings of audio streams.</para>
        /// <para>This function returns the opened device ID on success. This is a new, unique <see cref="CSDL.Audio.AudioDeviceID">AudioDeviceID</see> that represents a logical device.</para>
        /// <para>Some backends might offer arbitrary devices (for example, a networked audio protocol that can connect to an arbitrary server). For these, as a change from SDL2, you should open a default device ID and use an SDL hint to specify the target if you care, or otherwise let the backend figure out a reasonable default. Most backends don't offer anything like this, and often this would be an end user setting an environment variable for their custom need, and not something an application should specifically manage.</para>
        /// <para>When done with an audio device, possibly at the end of the app's life, one should call <c>SDL_CloseAudioDevice</c> on the returned device id.</para>
        /// </remarks>
        /// <param name="devid">the device instance id to open, or <see cref="CSDL.Audio.Macros.AudioDeviceDefaultPlayback">AudioDeviceDefaultPlayback</see> or <see cref="CSDL.Audio.Macros.AudioDeviceDefaultRecording">AudioDeviceDefaultRecording</see> for the most reasonable default device.</param>
        /// <param name="spec">the requested device configuration. Can be NULL to use reasonable defaults.</param>
        /// <returns>
        /// <para>(<see cref="CSDL.Audio.AudioDeviceID">AudioDeviceID</see>) Returns the device ID on success or 0 on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_OpenAudioDevice">SDL_OpenAudioDevice</seealso></SDLWiki>
        /// <seealso><c>SDL_CloseAudioDevice</c></seealso>
        /// <seealso><see cref="CSDL.Audio.PlaybackDevice.ResolveDefaultSpec">ResolveDefaultSpec</see></seealso>
        public static extern void OpenAudioDevice();

        /// <summary>
        /// <para>Convenience function for straightforward audio init for the common case.</para>
        /// </summary>
        /// <remarks>
        /// <para>If all your app intends to do is provide a single source of PCM audio, this function allows you to do all your audio setup in a single call.</para>
        /// <para>This is also intended to be a clean means to migrate apps from SDL2.</para>
        /// <para>This function will open an audio device, create a stream and bind it. Unlike other methods of setup, the audio device will be closed when this stream is destroyed, so the app can treat the returned <see cref="CSDL.Audio.AudioStream">AudioStream</see> as the only object needed to manage audio playback.</para>
        /// <para>Also unlike other functions, the audio device begins paused. This is to map more closely to SDL2-style behavior, since there is no extra step here to bind a stream to begin audio flowing. The audio device should be resumed with <see cref="CSDL.Audio.AudioStream.ResumeDevice">ResumeDevice</see>.</para>
        /// <para>This function works with both playback and recording devices.</para>
        /// <para>The <c>spec</c> parameter represents the app's side of the audio stream. That is, for recording audio, this will be the output format, and for playing audio, this will be the input format. If spec is NULL, the system will choose the format, and the app can use <see cref="CSDL.Audio.AudioStream.GetAudioStreamFormat">GetAudioStreamFormat</see> to obtain this information later.</para>
        /// <para>If you don't care about opening a specific audio device, you can (and probably _should_), use <see cref="CSDL.Audio.Macros.AudioDeviceDefaultPlayback">AudioDeviceDefaultPlayback</see> for playback and <see cref="CSDL.Audio.Macros.AudioDeviceDefaultRecording">AudioDeviceDefaultRecording</see> for recording.</para>
        /// <para>One can optionally provide a callback function; if NULL, the app is expected to queue audio data for playback (or unqueue audio data if capturing). Otherwise, the callback will begin to fire once the device is unpaused.</para>
        /// <para>Destroying the returned stream with <see cref="CSDL.Audio.AudioStream.DisposeResource">DisposeResource</see> will also close the audio device associated with this stream.</para>
        /// </remarks>
        /// <param name="devid">an audio device to open, or <see cref="CSDL.Audio.Macros.AudioDeviceDefaultPlayback">AudioDeviceDefaultPlayback</see> or <see cref="CSDL.Audio.Macros.AudioDeviceDefaultRecording">AudioDeviceDefaultRecording</see>.</param>
        /// <param name="spec">the audio stream's data format. Can be NULL.</param>
        /// <param name="callback">a callback where the app will provide new data for playback, or receive new data for recording. Can be NULL, in which case the app will need to call <see cref="CSDL.Audio.AudioStream.PutData">PutData</see> or <see cref="CSDL.Audio.AudioStream.GetData">GetData</see> as necessary.</param>
        /// <param name="userdata">app-controlled pointer passed to callback. Can be NULL. Ignored if callback is NULL.</param>
        /// <returns>
        /// <para>(<see cref="CSDL.Audio.AudioStream">AudioStream</see> *) Returns an audio stream on success, ready to use, or NULL on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information. When done with this stream, call <see cref="CSDL.Audio.AudioStream.DisposeResource">DisposeResource</see> to free resources and close the device.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_OpenAudioDeviceStream">SDL_OpenAudioDeviceStream</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.DeviceId">DeviceId</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.ResumeDevice">ResumeDevice</see></seealso>
        public static extern void OpenAudioDeviceStream();

        /// <summary>
        /// <para>Use this function to pause audio playback on a specified device.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function pauses audio processing for a given device. Any bound audio streams will not progress, and no audio will be generated. Pausing one device does not prevent other unpaused devices from running.</para>
        /// <para>Unlike in SDL2, audio devices start in an _unpaused_ state, since an app has to bind a stream before any audio will flow. Pausing a paused device is a legal no-op.</para>
        /// <para>Pausing a device can be useful to halt all audio without unbinding all the audio streams. This might be useful while a game is paused, or a level is loading, etc.</para>
        /// <para>Physical devices can not be paused or unpaused, only logical devices created through <c>SDL_OpenAudioDevice</c> can be.</para>
        /// </remarks>
        /// <param name="devid">a device opened by <c>SDL_OpenAudioDevice</c>.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_PauseAudioDevice">SDL_PauseAudioDevice</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioDeviceBase.Resume">Resume</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioDeviceBase.Paused">Paused</see></seealso>
        public static extern void PauseAudioDevice();

        /// <summary>
        /// <para>Use this function to pause audio playback on the audio device associated with an audio stream.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function pauses audio processing for a given device. Any bound audio streams will not progress, and no audio will be generated. Pausing one device does not prevent other unpaused devices from running.</para>
        /// <para>Pausing a device can be useful to halt all audio without unbinding all the audio streams. This might be useful while a game is paused, or a level is loading, etc.</para>
        /// </remarks>
        /// <param name="stream">the audio stream associated with the audio device to pause.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_PauseAudioStreamDevice">SDL_PauseAudioStreamDevice</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.ResumeDevice">ResumeDevice</see></seealso>
        public static extern void PauseAudioStreamDevice();

        /// <summary>
        /// <para>Add data to the stream.</para>
        /// </summary>
        /// <remarks>
        /// <para>This data must match the format/channels/samplerate specified in the latest call to <see cref="CSDL.Audio.AudioStream.SetAudioStreamFormat">SetAudioStreamFormat</see>, or the format specified when creating the stream if it hasn't been changed.</para>
        /// <para>Note that this call simply copies the unconverted data for later. This is different than SDL2, where data was converted during the Put call and the Get call would just dequeue the previously-converted data.</para>
        /// </remarks>
        /// <param name="stream">the stream the audio data is being added to.</param>
        /// <param name="buf">a pointer to the audio data to add.</param>
        /// <param name="len">the number of bytes to write to the stream.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread, but if the stream has a callback set, the caller might need to manage extra locking.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_PutAudioStreamData">SDL_PutAudioStreamData</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.Clear">Clear</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.Flush">Flush</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.GetData">GetData</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.Queued">Queued</see></seealso>
        public static extern void PutAudioStreamData();

        /// <summary>
        /// <para>Add external data to an audio stream without copying it.</para>
        /// </summary>
        /// <remarks>
        /// <para>Unlike <see cref="CSDL.Audio.AudioStream.PutData">PutData</see>, this function does not make a copy of the provided data, instead storing the provided pointer. This means that the put operation does not need to allocate and copy the data, but the original data must remain available until the stream is done with it, either by being read from the stream in its entirety, or a call to <see cref="CSDL.Audio.AudioStream.Clear">Clear</see> or <see cref="CSDL.Audio.AudioStream.DisposeResource">DisposeResource</see>.</para>
        /// <para>The data must match the format/channels/samplerate specified in the latest call to <see cref="CSDL.Audio.AudioStream.SetAudioStreamFormat">SetAudioStreamFormat</see>, or the format specified when creating the stream if it hasn't been changed.</para>
        /// <para>An optional callback may be provided, which is called when the stream no longer needs the data. Once this callback fires, the stream will not access the data again. This callback will fire for any reason the data is no longer needed, including clearing or destroying the stream.</para>
        /// <para>Note that there is still an allocation to store tracking information, so this function is more efficient for larger blocks of data. If you're planning to put a few samples at a time, it will be more efficient to use <see cref="CSDL.Audio.AudioStream.PutData">PutData</see>, which allocates and buffers in blocks.</para>
        /// </remarks>
        /// <param name="stream">the stream the audio data is being added to.</param>
        /// <param name="buf">a pointer to the audio data to add.</param>
        /// <param name="len">the number of bytes to add to the stream.</param>
        /// <param name="callback">the callback function to call when the data is no longer needed by the stream. May be NULL.</param>
        /// <param name="userdata">an opaque pointer provided to the callback for its own personal use.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread, but if the stream has a callback set, the caller might need to manage extra locking.</threadsafety>
        /// <since>This function is available since SDL 3.4.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_PutAudioStreamDataNoCopy">SDL_PutAudioStreamDataNoCopy</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.Clear">Clear</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.Flush">Flush</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.GetData">GetData</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.Queued">Queued</see></seealso>
        public static extern void PutAudioStreamDataNoCopy();

        /// <summary>
        /// <para>Add data to the stream with each channel in a separate array.</para>
        /// </summary>
        /// <remarks>
        /// <para>This data must match the format/channels/samplerate specified in the latest call to <see cref="CSDL.Audio.AudioStream.SetAudioStreamFormat">SetAudioStreamFormat</see>, or the format specified when creating the stream if it hasn't been changed.</para>
        /// <para>The data will be interleaved and queued. Note that <see cref="CSDL.Audio.AudioStream">AudioStream</see> only operates on interleaved data, so this is simply a convenience function for easily queueing data from sources that provide separate arrays. There is no equivalent function to retrieve planar data.</para>
        /// <para>The arrays in <c>channel_buffers</c> are ordered as they are to be interleaved; the first array will be the first sample in the interleaved data. Any individual array may be NULL; in this case, silence will be interleaved for that channel.</para>
        /// <para><c>num_channels</c> specifies how many arrays are in <c>channel_buffers</c>. This can be used as a safety to prevent overflow, in case the stream format has changed elsewhere. If more channels are specified than the current input spec, they are ignored. If less channels are specified, the missing arrays are treated as if they are NULL (silence is written to those channels). If the count is -1, SDL will assume the array count matches the current input spec.</para>
        /// <para>Note that <c>num_samples</c> is the number of _samples per array_. This can also be thought of as the number of _sample frames_ to be queued. A value of 1 with stereo arrays will queue two samples to the stream. This is different than <see cref="CSDL.Audio.AudioStream.PutData">PutData</see>, which wants the size of a single array in bytes.</para>
        /// </remarks>
        /// <param name="stream">the stream the audio data is being added to.</param>
        /// <param name="channel_buffers">a pointer to an array of arrays, one array per channel.</param>
        /// <param name="num_channels">the number of arrays in <c>channel_buffers</c> or -1.</param>
        /// <param name="num_samples">the number of _samples_ per array to write to the stream.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread, but if the stream has a callback set, the caller might need to manage extra locking.</threadsafety>
        /// <since>This function is available since SDL 3.4.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_PutAudioStreamPlanarData">SDL_PutAudioStreamPlanarData</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.Clear">Clear</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.Flush">Flush</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.GetData">GetData</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.Queued">Queued</see></seealso>
        public static extern void PutAudioStreamPlanarData();

        /// <summary>
        /// <para>Use this function to unpause audio playback on a specified device.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function unpauses audio processing for a given device that has previously been paused with <see cref="CSDL.Audio.AudioDeviceBase.Pause">Pause</see>. Once unpaused, any bound audio streams will begin to progress again, and audio can be generated.</para>
        /// <para>Unlike in SDL2, audio devices start in an _unpaused_ state, since an app has to bind a stream before any audio will flow. Unpausing an unpaused device is a legal no-op.</para>
        /// <para>Physical devices can not be paused or unpaused, only logical devices created through <c>SDL_OpenAudioDevice</c> can be.</para>
        /// </remarks>
        /// <param name="devid">a device opened by <c>SDL_OpenAudioDevice</c>.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_ResumeAudioDevice">SDL_ResumeAudioDevice</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioDeviceBase.Paused">Paused</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioDeviceBase.Pause">Pause</see></seealso>
        public static extern void ResumeAudioDevice();

        /// <summary>
        /// <para>Use this function to unpause audio playback on the audio device associated with an audio stream.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function unpauses audio processing for a given device that has previously been paused. Once unpaused, any bound audio streams will begin to progress again, and audio can be generated.</para>
        /// <para><c>SDL_OpenAudioDeviceStream</c> opens audio devices in a paused state, so this function call is required for audio playback to begin on such devices.</para>
        /// </remarks>
        /// <param name="stream">the audio stream associated with the audio device to resume.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_ResumeAudioStreamDevice">SDL_ResumeAudioStreamDevice</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.PauseDevice">PauseDevice</see></seealso>
        public static extern void ResumeAudioStreamDevice();

        /// <summary>
        /// <para>Change the gain of an audio device.</para>
        /// </summary>
        /// <remarks>
        /// <para>The gain of a device is its volume; a larger gain means a louder output, with a gain of zero being silence.</para>
        /// <para>Audio devices default to a gain of 1.0f (no change in output).</para>
        /// <para>Physical devices may not have their gain changed, only logical devices, and this function will always return false when used on physical devices. While it might seem attractive to adjust several logical devices at once in this way, it would allow an app or library to interfere with another portion of the program's otherwise-isolated devices.</para>
        /// <para>This is applied, along with any per-audiostream gain, during playback to the hardware, and can be continuously changed to create various effects. On recording devices, this will adjust the gain before passing the data into an audiostream; that recording audiostream can then adjust its gain further when outputting the data elsewhere, if it likes, but that second gain is not applied until the data leaves the audiostream again.</para>
        /// </remarks>
        /// <param name="devid">the audio device on which to change gain.</param>
        /// <param name="gain">the gain. 1.0f is no change, 0.0f is silence.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread, as it holds a stream-specific mutex while running.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetAudioDeviceGain">SDL_SetAudioDeviceGain</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioDeviceBase.GetGain">GetGain</see></seealso>
        public static extern void SetAudioDeviceGain();

        /// <summary>
        /// <para>Set a callback that fires when data is about to be fed to an audio device.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is useful for accessing the final mix, perhaps for writing a visualizer or applying a final effect to the audio data before playback.</para>
        /// <para>The buffer is the final mix of all bound audio streams on an opened device; this callback will fire regularly for any device that is both opened and unpaused. If there is no new data to mix, either because no streams are bound to the device or all the streams are empty, this callback will still fire with the entire buffer set to silence.</para>
        /// <para>This callback is allowed to make changes to the data; the contents of the buffer after this call is what is ultimately passed along to the hardware.</para>
        /// <para>The callback is always provided the data in float format (values from -1.0f to 1.0f), but the number of channels or sample rate may be different than the format the app requested when opening the device; SDL might have had to manage a conversion behind the scenes, or the playback might have jumped to new physical hardware when a system default changed, etc. These details may change between calls. Accordingly, the size of the buffer might change between calls as well.</para>
        /// <para>This callback can run at any time, and from any thread; if you need to serialize access to your app's data, you should provide and use a mutex or other synchronization device.</para>
        /// <para>All of this to say: there are specific needs this callback can fulfill, but it is not the simplest interface. Apps should generally provide audio in their preferred format through an <see cref="CSDL.Audio.AudioStream">AudioStream</see> and let SDL handle the difference.</para>
        /// <para>This function is extremely time-sensitive; the callback should do the least amount of work possible and return as quickly as it can. The longer the callback runs, the higher the risk of audio dropouts or other problems.</para>
        /// <para>This function will block until the audio device is in between iterations, so any existing callback that might be running will finish before this function sets the new callback and returns.</para>
        /// <para>Setting a NULL callback function disables any previously-set callback.</para>
        /// </remarks>
        /// <param name="devid">the ID of an opened audio device.</param>
        /// <param name="callback">a callback function to be called. Can be NULL.</param>
        /// <param name="userdata">app-controlled pointer passed to callback. Can be NULL.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetAudioPostmixCallback">SDL_SetAudioPostmixCallback</seealso></SDLWiki>
        public static extern void SetAudioPostmixCallback();

        /// <summary>
        /// <para>Change the input and output formats of an audio stream.</para>
        /// </summary>
        /// <remarks>
        /// <para>Future calls to and <see cref="CSDL.Audio.AudioStream.Available">Available</see> and <see cref="CSDL.Audio.AudioStream.GetData">GetData</see> will reflect the new format, and future calls to <see cref="CSDL.Audio.AudioStream.PutData">PutData</see> must provide data in the new input formats.</para>
        /// <para>Data that was previously queued in the stream will still be operated on in the format that was current when it was added, which is to say you can put the end of a sound file in one format to a stream, change formats for the next sound file, and start putting that new data while the previous sound file is still queued, and everything will still play back correctly.</para>
        /// <para>If a stream is bound to a device, then the format of the side of the stream bound to a device cannot be changed (src_spec for recording devices, dst_spec for playback devices). Attempts to make a change to this side will be ignored, but this will not report an error. The other side's format can be changed.</para>
        /// <para><c>src_spec</c> and <c>dst_spec</c> may each be NULL; a NULL spec signals not to change the current format for that side of the stream.</para>
        /// </remarks>
        /// <param name="stream">the stream the format is being changed.</param>
        /// <param name="src_spec">the new format of the audio input; if NULL, it is not changed.</param>
        /// <param name="dst_spec">the new format of the audio output; if NULL, it is not changed.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread, as it holds a stream-specific mutex while running.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetAudioStreamFormat">SDL_SetAudioStreamFormat</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.GetAudioStreamFormat">GetAudioStreamFormat</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.FrequencyRatio">FrequencyRatio</see></seealso>
        public static extern void SetAudioStreamFormat();

        /// <summary>
        /// <para>Change the frequency ratio of an audio stream.</para>
        /// </summary>
        /// <remarks>
        /// <para>The frequency ratio is used to adjust the rate at which input data is consumed. Changing this effectively modifies the speed and pitch of the audio. A value greater than 1.0f will play the audio faster, and at a higher pitch. A value less than 1.0f will play the audio slower, and at a lower pitch. 1.0f means play at normal speed.</para>
        /// <para>This is applied during <see cref="CSDL.Audio.AudioStream.GetData">GetData</see>, and can be continuously changed to create various effects.</para>
        /// </remarks>
        /// <param name="stream">the stream on which the frequency ratio is being changed.</param>
        /// <param name="ratio">the frequency ratio. 1.0 is normal speed. Must be between 0.01 and 100.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread, as it holds a stream-specific mutex while running.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetAudioStreamFrequencyRatio">SDL_SetAudioStreamFrequencyRatio</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.GetAudioStreamFrequencyRatio">GetAudioStreamFrequencyRatio</see></seealso>
        /// <seealso><see cref="CSDL.Audio.AudioStream.SetAudioStreamFormat">SetAudioStreamFormat</see></seealso>
        public static extern void SetAudioStreamFrequencyRatio();

        /// <summary>
        /// <para>Change the gain of an audio stream.</para>
        /// </summary>
        /// <remarks>
        /// <para>The gain of a stream is its volume; a larger gain means a louder output, with a gain of zero being silence.</para>
        /// <para>Audio streams default to a gain of 1.0f (no change in output).</para>
        /// <para>This is applied during <see cref="CSDL.Audio.AudioStream.GetData">GetData</see>, and can be continuously changed to create various effects.</para>
        /// </remarks>
        /// <param name="stream">the stream on which the gain is being changed.</param>
        /// <param name="gain">the gain. 1.0f is no change, 0.0f is silence.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread, as it holds a stream-specific mutex while running.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetAudioStreamGain">SDL_SetAudioStreamGain</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.GetAudioStreamGain">GetAudioStreamGain</see></seealso>
        public static extern void SetAudioStreamGain();

        /// <summary>
        /// <para>Set a callback that runs when data is requested from an audio stream.</para>
        /// </summary>
        /// <remarks>
        /// <para>This callback is called _before_ data is obtained from the stream, giving the callback the chance to add more on-demand.</para>
        /// <para>The callback can (optionally) call <see cref="CSDL.Audio.AudioStream.PutData">PutData</see> to add more audio to the stream during this call; if needed, the request that triggered this callback will obtain the new data immediately.</para>
        /// <para>The callback's <c>additional_amount</c> argument is roughly how many bytes of _unconverted_ data (in the stream's input format) is needed by the caller, although this may overestimate a little for safety. This takes into account how much is already in the stream and only asks for any extra necessary to resolve the request, which means the callback may be asked for zero bytes, and a different amount on each call.</para>
        /// <para>The callback is not required to supply exact amounts; it is allowed to supply too much or too little or none at all. The caller will get what's available, up to the amount they requested, regardless of this callback's outcome.</para>
        /// <para>Clearing or flushing an audio stream does not call this callback.</para>
        /// <para>This function obtains the stream's lock, which means any existing callback (get or put) in progress will finish running before setting the new callback.</para>
        /// <para>Setting a NULL function turns off the callback.</para>
        /// </remarks>
        /// <param name="stream">the audio stream to set the new callback on.</param>
        /// <param name="callback">the new callback function to call when data is requested from the stream.</param>
        /// <param name="userdata">an opaque pointer provided to the callback for its own personal use.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information. This only fails if <c>stream</c> is NULL.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetAudioStreamGetCallback">SDL_SetAudioStreamGetCallback</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.SetPutCallback">SetPutCallback</see></seealso>
        public static extern void SetAudioStreamGetCallback();

        /// <summary>
        /// <para>Set the current input channel map of an audio stream.</para>
        /// </summary>
        /// <remarks>
        /// <para>Channel maps are optional; most things do not need them, instead passing data in the <c>CategoryAudio#channel-layouts</c>.</para>
        /// <para>The input channel map reorders data that is added to a stream via <see cref="CSDL.Audio.AudioStream.PutData">PutData</see>. Future calls to <see cref="CSDL.Audio.AudioStream.PutData">PutData</see> must provide data in the new channel order.</para>
        /// <para>Each item in the array represents an input channel, and its value is the channel that it should be remapped to. To reverse a stereo signal's left and right values, you'd have an array of <c>{ 1, 0 }</c>. It is legal to remap multiple channels to the same thing, so <c>{ 1, 1 }</c> would duplicate the right channel to both channels of a stereo signal. An element in the channel map set to -1 instead of a valid channel will mute that channel, setting it to a silence value.</para>
        /// <para>You cannot change the number of channels through a channel map, just reorder/mute them.</para>
        /// <para>Data that was previously queued in the stream will still be operated on in the order that was current when it was added, which is to say you can put the end of a sound file in one order to a stream, change orders for the next sound file, and start putting that new data while the previous sound file is still queued, and everything will still play back correctly.</para>
        /// <para>Audio streams default to no remapping applied. Passing a NULL channel map is legal, and turns off remapping.</para>
        /// <para>SDL will copy the channel map; the caller does not have to save this array after this call.</para>
        /// <para>If <c>count</c> is not equal to the current number of channels in the audio stream's format, this will fail. This is a safety measure to make sure a race condition hasn't changed the format while this call is setting the channel map.</para>
        /// <para>Unlike attempting to change the stream's format, the input channel map on a stream bound to a recording device is permitted to change at any time; any data added to the stream from the device after this call will have the new mapping, but previously-added data will still have the prior mapping.</para>
        /// </remarks>
        /// <param name="stream">the <see cref="CSDL.Audio.AudioStream">AudioStream</see> to change.</param>
        /// <param name="chmap">the new channel map, NULL to reset to default.</param>
        /// <param name="count">The number of channels in the map.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread, as it holds a stream-specific mutex while running. Don't change the stream's format to have a different number of channels from a different thread at the same time, though!</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetAudioStreamInputChannelMap">SDL_SetAudioStreamInputChannelMap</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.SetOutputChannelMap">SetOutputChannelMap</see></seealso>
        public static extern void SetAudioStreamInputChannelMap();

        /// <summary>
        /// <para>Set the current output channel map of an audio stream.</para>
        /// </summary>
        /// <remarks>
        /// <para>Channel maps are optional; most things do not need them, instead passing data in the <c>CategoryAudio#channel-layouts</c>.</para>
        /// <para>The output channel map reorders data that is leaving a stream via <see cref="CSDL.Audio.AudioStream.GetData">GetData</see>.</para>
        /// <para>Each item in the array represents an input channel, and its value is the channel that it should be remapped to. To reverse a stereo signal's left and right values, you'd have an array of <c>{ 1, 0 }</c>. It is legal to remap multiple channels to the same thing, so <c>{ 1, 1 }</c> would duplicate the right channel to both channels of a stereo signal. An element in the channel map set to -1 instead of a valid channel will mute that channel, setting it to a silence value.</para>
        /// <para>You cannot change the number of channels through a channel map, just reorder/mute them.</para>
        /// <para>The output channel map can be changed at any time, as output remapping is applied during <see cref="CSDL.Audio.AudioStream.GetData">GetData</see>.</para>
        /// <para>Audio streams default to no remapping applied. Passing a NULL channel map is legal, and turns off remapping.</para>
        /// <para>SDL will copy the channel map; the caller does not have to save this array after this call.</para>
        /// <para>If <c>count</c> is not equal to the current number of channels in the audio stream's format, this will fail. This is a safety measure to make sure a race condition hasn't changed the format while this call is setting the channel map.</para>
        /// <para>Unlike attempting to change the stream's format, the output channel map on a stream bound to a recording device is permitted to change at any time; any data added to the stream after this call will have the new mapping, but previously-added data will still have the prior mapping. When the channel map doesn't match the hardware's channel layout, SDL will convert the data before feeding it to the device for playback.</para>
        /// </remarks>
        /// <param name="stream">the <see cref="CSDL.Audio.AudioStream">AudioStream</see> to change.</param>
        /// <param name="chmap">the new channel map, NULL to reset to default.</param>
        /// <param name="count">The number of channels in the map.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread, as it holds a stream-specific mutex while running. Don't change the stream's format to have a different number of channels from a a different thread at the same time, though!</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetAudioStreamOutputChannelMap">SDL_SetAudioStreamOutputChannelMap</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.SetInputChannelMap">SetInputChannelMap</see></seealso>
        public static extern void SetAudioStreamOutputChannelMap();

        /// <summary>
        /// <para>Set a callback that runs when data is added to an audio stream.</para>
        /// </summary>
        /// <remarks>
        /// <para>This callback is called _after_ the data is added to the stream, giving the callback the chance to obtain it immediately.</para>
        /// <para>The callback can (optionally) call <see cref="CSDL.Audio.AudioStream.GetData">GetData</see> to obtain audio from the stream during this call.</para>
        /// <para>The callback's <c>additional_amount</c> argument is how many bytes of _converted_ data (in the stream's output format) was provided by the caller, although this may underestimate a little for safety. This value might be less than what is currently available in the stream, if data was already there, and might be less than the caller provided if the stream needs to keep a buffer to aid in resampling. Which means the callback may be provided with zero bytes, and a different amount on each call.</para>
        /// <para>The callback may call <see cref="CSDL.Audio.AudioStream.Available">Available</see> to see the total amount currently available to read from the stream, instead of the total provided by the current call.</para>
        /// <para>The callback is not required to obtain all data. It is allowed to read less or none at all. Anything not read now simply remains in the stream for later access.</para>
        /// <para>Clearing or flushing an audio stream does not call this callback.</para>
        /// <para>This function obtains the stream's lock, which means any existing callback (get or put) in progress will finish running before setting the new callback.</para>
        /// <para>Setting a NULL function turns off the callback.</para>
        /// </remarks>
        /// <param name="stream">the audio stream to set the new callback on.</param>
        /// <param name="callback">the new callback function to call when data is added to the stream.</param>
        /// <param name="userdata">an opaque pointer provided to the callback for its own personal use.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information. This only fails if <c>stream</c> is NULL.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetAudioStreamPutCallback">SDL_SetAudioStreamPutCallback</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.SetGetCallback">SetGetCallback</see></seealso>
        public static extern void SetAudioStreamPutCallback();

        /// <summary>
        /// <para>Unbind a single audio stream from its audio device.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is a convenience function, equivalent to calling <c>SDL_UnbindAudioStreams(&amp;stream, 1)</c>.</para>
        /// </remarks>
        /// <param name="stream">an audio stream to unbind from a device. Can be NULL.</param>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UnbindAudioStream">SDL_UnbindAudioStream</seealso></SDLWiki>
        /// <seealso><c>SDL_BindAudioStream</c></seealso>
        public static extern void UnbindAudioStream();

        /// <summary>
        /// <para>Unbind a list of audio streams from their audio devices.</para>
        /// </summary>
        /// <remarks>
        /// <para>The streams being unbound do not all have to be on the same device. All streams on the same device will be unbound atomically (data will stop flowing through all unbound streams on the same device at the same time).</para>
        /// <para>Unbinding a stream that isn't bound to a device is a legal no-op.</para>
        /// </remarks>
        /// <param name="streams">an array of audio streams to unbind. Can be NULL or contain NULL.</param>
        /// <param name="num_streams">number streams listed in the <c>streams</c> array.</param>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UnbindAudioStreams">SDL_UnbindAudioStreams</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioDeviceBase.BindStreams">BindStreams</see></seealso>
        public static extern void UnbindAudioStreams();

        /// <summary>
        /// <para>Unlock an audio stream for serialized access.</para>
        /// </summary>
        /// <remarks>
        /// <para>This unlocks an audio stream after a call to <see cref="CSDL.Audio.AudioStream.AcquireLock">AcquireLock</see>.</para>
        /// </remarks>
        /// <param name="stream">the audio stream to unlock.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>You should only call this from the same thread that previously called <see cref="CSDL.Audio.AudioStream.AcquireLock">AcquireLock</see>.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UnlockAudioStream">SDL_UnlockAudioStream</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Audio.AudioStream.AcquireLock">AcquireLock</see></seealso>
        public static extern void UnlockAudioStream();
    }
}
